package io.github.jesterportfolio.hearth.quest;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.exploration.*;
import io.github.jesterportfolio.hearth.story.*;
import io.github.jesterportfolio.hearth.inventory.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class BranchProgressionTest {
    static QuestCatalog catalog(){return QuestCatalog.parse(List.of(QuestCatalogTest.npc("survey_guide",3),QuestCatalogTest.npc("path_guide",10)),List.of(QuestCatalogTest.quest("survey_marker","survey_guide"),QuestCatalogTest.quest("path_marker","path_guide"),QuestCatalogTest.quest("one_quest","survey_guide"),QuestCatalogTest.quest("two_quest","survey_guide")));}
    static Map<String,Object> chapter(){return new HashMap<>(Map.of("id","chapter","title","공개 선택 장","shared-stage","vote","required-quests",List.of(),"branch-stage","vote","branch-quests",Map.of("one",List.of("one_quest"),"two",List.of("two_quest"))));}
    static Map<String,Object> rule(){return new HashMap<>(Map.of("id","one_quest","restart","KEEP","failures",List.of(),"checkpoints",List.of(),"timeout-seconds",0,"reward",Map.of("items",List.of(Map.of("material","STONE","amount",1)))));}
    static QuestRules rules(){return parse(chapter(),List.of(rule()));}
    static QuestRules parse(Map<String,Object> chapter,List<?> rules){var c=catalog();return QuestRules.parse(Map.of("format",1,"quests",rules,"chapters",List.of(chapter)),c,StoryContent.parse(SharedStoryTest.root(),c,ExplorationTest.content()));}
    static StoryStore.Snapshot shared(String choice){return new StoryStore.Snapshot(new ExplorationStore.Story("open","공개 단계",true,2),Set.of("arrival","vote"),choice==null?Map.of():Map.of("vote",new StoryStore.Branch("vote",choice,"공개 확정 경로",UUID.randomUUID())));}
    static Map<String,QuestStore.Saved> states(QuestStore.Phase phase){var rows=new HashMap<String,QuestStore.Saved>();for(String q:catalog().questIds())rows.put(q,new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));rows.put("one_quest",new QuestStore.Saved(phase,phase==QuestStore.Phase.NOT_ACCEPTED?-1:2));return rows;}
    static QuestJournal.View view(QuestRules rules,QuestStore.Phase phase,Map<String,QuestCompletionStore.RewardRecord> rewards,Map<String,QuestCompletionStore.ChapterState> skips){var states=states(phase);var info=QuestCompletionView.build(catalog(),rules,states,Set.of("two_quest"),rewards,skips,shared("one"),4);return new QuestJournal.View(states,new QuestJournalStore.Journal(Set.of(),new QuestJournalStore.Preferences(true,-1),List.of()),ExplorationView.empty(),info);}
    @Test void compilerBindsOnlySelectedLineAndKeepsFlatDefinitionFingerprint(){var r=rules();assertEquals(new QuestRules.BranchGate("vote","one"),r.rule("one_quest").branch());assertEquals(List.of("one_quest"),r.chapters().get("chapter").selected(shared("one")).orElseThrow());assertEquals(List.of("two_quest"),r.chapters().get("chapter").selected(shared("two")).orElseThrow());assertTrue(r.chapters().get("chapter").selected(shared(null)).isEmpty());
        var reverse=chapter();reverse.put("branch-quests",new LinkedHashMap<>(Map.of("two",List.of("two_quest"),"one",List.of("one_quest"))));assertEquals(r.chapters().get("chapter").fingerprint(),parse(reverse,List.of(rule())).chapters().get("chapter").fingerprint());
        var flat=new HashMap<String,Object>(Map.of("id","flat","title","공개 장","shared-stage","arrival","required-quests",List.of("one_quest")));var parsed=parse(flat,List.of());try{var expected=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest("arrival[one_quest]".getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertEquals(expected,parsed.chapters().get("flat").fingerprint());}catch(Exception e){throw new AssertionError(e);}}
    @Test void invalidAndConflictingBranchContentFailsBeforeActivation(){for(Object bad:List.of(Map.of("one",List.of("one_quest")),Map.of("one",List.of("missing"),"two",List.of("two_quest")),Map.of("one",List.of("one_quest"),"two",List.of("one_quest")))){var c=chapter();c.put("branch-quests",bad);assertThrows(IllegalArgumentException.class,()->parse(c,List.of()));}
        var rule=rule();rule.put("requires-branch",Map.of("stage","vote","choice","two"));assertThrows(IllegalArgumentException.class,()->parse(chapter(),List.of(rule)));rule.put("requires-branch",Map.of("stage","missing","choice","one"));assertThrows(IllegalArgumentException.class,()->parse(chapter(),List.of(rule)));}
    @Test void rewardStatusAndClaimabilityAreDataDrivenAndNeverCreateMissingRecords(){var rules=rules();var hash=rules.rule("one_quest").reward().fingerprint();for(String status:List.of("PENDING","GRANTED","POLICY_PENDING")){var v=view(rules,QuestStore.Phase.COMPLETED,Map.of("one_quest",new QuestCompletionStore.RewardRecord(status,hash)),Map.of());assertEquals(status,v.completion().rewards().get("one_quest").status());assertEquals(status.equals("PENDING"),v.completion().rewards().get("one_quest").claimable());assertEquals(status.equals("PENDING"),QuestScreens.screen(catalog(),v,"detail","one_quest",0).stream().anyMatch(b->b.action().equals("quest-reward")));}
        var missing=view(rules,QuestStore.Phase.COMPLETED,Map.of(),Map.of());assertEquals("UNREGISTERED",missing.completion().rewards().get("one_quest").status());var mismatch=view(rules,QuestStore.Phase.COMPLETED,Map.of("one_quest",new QuestCompletionStore.RewardRecord("PENDING","other")),Map.of());assertEquals("CONFIG_MISMATCH",mismatch.completion().rewards().get("one_quest").status());assertFalse(mismatch.completion().rewards().get("one_quest").claimable());}
    @Test void chapterScreensHideOtherBranchAndUnacceptedNamesAndRequireConfirmation(){var r=rules();var initial=view(r,QuestStore.Phase.NOT_ACCEPTED,Map.of(),Map.of());assertEquals(1,initial.completion().chapter("chapter").orElseThrow().unaccepted());assertTrue(initial.completion().chapter("chapter").orElseThrow().parts().isEmpty());assertFalse(initial.completion().toString().contains("two_quest"));var shown=QuestScreens.screen(catalog(),initial,"chapter-detail","chapter",0);assertFalse(shown.toString().contains("공개 시험 one_quest"));assertTrue(shown.stream().anyMatch(b->b.action().equals("chapter-confirm")));assertFalse(shown.stream().anyMatch(b->b.action().equals("quest-chapter-skip")));var confirm=QuestScreens.screen(catalog(),initial,"chapter-confirm","chapter",0);assertTrue(confirm.stream().anyMatch(b->b.action().equals("quest-chapter-skip")));assertTrue(confirm.stream().anyMatch(b->b.slot()==45&&"chapter".equals(b.quest())));
        var skipped=view(r,QuestStore.Phase.SKIPPED,Map.of(),Map.of("chapter",new QuestCompletionStore.ChapterState("chapter",r.chapters().get("chapter").fingerprint(),0)));assertFalse(QuestScreens.screen(catalog(),skipped,"chapter-confirm","chapter",0).stream().anyMatch(b->b.action().equals("quest-chapter-skip")));assertThrows(IllegalStateException.class,()->view(r,QuestStore.Phase.SKIPPED,Map.of(),Map.of("chapter",new QuestCompletionStore.ChapterState("chapter","mismatch",0))));}
    static final class Receipts implements QuestCompletionStore {boolean fail,delay;CompletableFuture<Map<String,RewardRecord>> reading;
        public CompletionStage<Map<String,RewardRecord>> readRewards(ServerProgressAccess.Context c){if(fail)return CompletableFuture.failedFuture(new StorageFailure("reward","08006"));if(delay){reading=new CompletableFuture<>();return reading;}return CompletableFuture.completedFuture(Map.of());}
        public CompletionStage<Map<String,ChapterState>> readChapters(ServerProgressAccess.Context c){return CompletableFuture.completedFuture(Map.of());}
        public CompletionStage<String> rewardStatus(ServerProgressAccess.Context c,String q){throw new AssertionError();}public CompletionStage<InventoryStore.Stored> grantReward(ServerProgressAccess.Context c,String q,String h,long r,InventoryPayload p){throw new AssertionError();}public CompletionStage<ChapterState> skipChapter(ServerProgressAccess.Context c,QuestRules.Chapter ch){throw new AssertionError();}}
    @Test void metadataFailureStaleSessionAndGenerationNeverBecomeEmptySuccess(){var f=new PersonalQuestTest.Fixture(true);var store=new Receipts();var journal=new QuestJournal(new QuestBatchTest.JournalStore(),f.quests,QuestCatalogTest.catalog(),f.queue::add,()->{});journal.completion(store,QuestRules.empty());var ctx=f.ctx(f.a,f.p);Object token=new Object();var load=journal.load(ctx,token,()->f.valid);f.pump();var old=load.toCompletableFuture().join();journal.invalidateCompletion(ctx);assertThrows(IllegalStateException.class,()->journal.requireView(ctx,old));
        store.fail=true;var failed=journal.load(ctx,token,()->f.valid);f.pump();assertTrue(failed.toCompletableFuture().isCompletedExceptionally());store.fail=false;store.delay=true;var pending=journal.load(ctx,token,()->f.valid);f.pump();var barrier=journal.barrier(f.a);assertFalse(barrier.toCompletableFuture().isDone());f.valid=false;store.reading.complete(Map.of());f.pump();assertTrue(pending.toCompletableFuture().isCompletedExceptionally());assertTrue(barrier.toCompletableFuture().isDone());
        f.valid=true;var epoch=journal.load(ctx,new Object(),()->true);f.pump();journal.invalidateRun(f.a);store.reading.complete(Map.of());f.pump();assertTrue(epoch.toCompletableFuture().isCompletedExceptionally());}
    @Test void branchGuardIsInactiveUntilRulesLoadAndKnownRejectionDoesNotHold(){var f=new PersonalQuestTest.Fixture();f.quests.requireRules(Set.of("survey_marker"));var ctx=f.ctx(f.a,f.p);var q=f.open(ctx,new Object());assertTrue(f.quests.accept(q,QuestCatalogTest.catalog().quest("survey_marker")).toCompletableFuture().isCompletedExceptionally());assertTrue(f.store.pending.isEmpty());
        var g=new PersonalQuestTest.Fixture();var active=g.open(g.ctx(g.a,g.p),new Object());var result=g.quests.accept(active,QuestCatalogTest.catalog().quest("survey_marker"));g.store.pending.getFirst().completeExceptionally(new StorageFailure("quest","QUEST_BRANCH_LOCKED"));g.pump();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertFalse(active.held());assertFalse(g.quests.barrier(g.a).toCompletableFuture().isCompletedExceptionally());}
}
